class Solution {
public:
    string convert(string s, int numRows) {
        int n = s.size();
        if (numRows == 1 || numRows >= n) return s;

        vector<string> rows(numRows);
        int curRow = 0;
        int step = -1;                     // will become +1 on first iteration

        for (char c : s) {
            rows[curRow] += c;
            if (curRow == 0 || curRow == numRows - 1) step = -step;
            curRow += step;
        }

        string result;
        result.reserve(n);
        for (auto &r : rows) result += r;
        return result;
    }
};
